const raw = $json.message?.content;
let parsed; try { parsed = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, riskMarkdown: '', error: 'JSON parse failed' } }]; }
const md = String(parsed?.markdown || '');
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
return [{ json: { valid: md.startsWith('# Risk Assessment:'), riskMarkdown: md, riskHash: fnv1a(md) } }];

