const raw = $json.message?.content;
let p; try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return [{ json: { valid: false, error: 'JSON parse failed' } }]; }
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < (s||'').length; i++) { h ^= s.charCodeAt(i); h = (h * 0x01000193) >>> 0; } return ('0000000' + h.toString(16)).slice(-8); };
const valid = p.testStrategyMarkdown && p.testStrategyMarkdown.startsWith('# Test Strategy:');
return [{ json: { valid, testStrategyMarkdown: p.testStrategyMarkdown || '', testScenariosMarkdown: p.testScenariosMarkdown || '', hashes: { strategy: fnv1a(p.testStrategyMarkdown), scenarios: fnv1a(p.testScenariosMarkdown) } } }];

const j = $json;
if (!j.valid) return [];
const ctx = $('Pass Context').first().json;
const meta = { jobId: ctx.jobId, stage: 'qa-compliance' };
const out = [];
out.push({ json: { artifactType: 'test_strategy_md', content: { markdown: j.testStrategyMarkdown }, contentHash: j.hashes.strategy, meta } });
out.push({ json: { artifactType: 'test_scenarios_md', content: { markdown: j.testScenariosMarkdown }, contentHash: j.hashes.scenarios, meta } });
return out;

const ctx = $('Pass Context').first().json;
const risk = $('Validate Risk').first().json;
const qa = $('Validate QA').first().json;
const projectSlug = ctx.projectSlug;
const jobId = ctx.jobId;
const repoDir = '/opt/workspace/software-delivery';
const projectDir = repoDir + '/' + projectSlug + '-docs';
const remote = 'git@github.com:shlapolosa/software-delivery.git';

const safeHeredoc = (content, marker) => {
  if (!content) return '';
  return String(content).replace(new RegExp(marker, 'g'), marker + '_ESCAPED');
};

let sh = `set -e
mkdir -p /opt/workspace

if [ ! -d '${repoDir}/.git' ]; then
  git clone '${remote}' '${repoDir}'
fi
cd '${repoDir}'
git fetch origin --prune

git checkout -B '${projectSlug}' 'origin/${projectSlug}' 2>/dev/null || git checkout -B '${projectSlug}'
mkdir -p '${projectDir}/docs'
`;

// Risk Assessment
sh += `cat > '${projectDir}/docs/risk-assessment.md' <<'EOFRISK_${jobId}'
${safeHeredoc(risk.riskMarkdown, 'EOFRISK_' + jobId)}
EOFRISK_${jobId}
`;

// Test Strategy
sh += `cat > '${projectDir}/docs/test-strategy.md' <<'EOFSTRAT_${jobId}'
${safeHeredoc(qa.testStrategyMarkdown, 'EOFSTRAT_' + jobId)}
EOFSTRAT_${jobId}
`;

// Test Scenarios
sh += `cat > '${projectDir}/docs/test-scenarios.md' <<'EOFSCEN_${jobId}'
${safeHeredoc(qa.testScenariosMarkdown, 'EOFSCEN_' + jobId)}
EOFSCEN_${jobId}
`;

sh += `
git add '${projectSlug}-docs'
git commit -m 'Add QA and compliance artifacts for ${projectSlug} (job ${jobId})' || true
git push -u origin '${projectSlug}'
`;

return [{ json: { ...ctx, gitScript: sh } }];

const ctx = $('Pass Context').first().json;
return [{ json: {
  success: true,
  jobId: ctx.jobId,
  projectSlug: ctx.projectSlug,
  stage: 'qa-compliance',
  artifacts: {
    riskAssessment: ctx.projectSlug + '-docs/docs/risk-assessment.md',
    testStrategy: ctx.projectSlug + '-docs/docs/test-strategy.md',
    testScenarios: ctx.projectSlug + '-docs/docs/test-scenarios.md'
  }
} }];
